'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='afterglow-v1',G=Game;
let state=null,screen='title',timer=null;
const read=(k,f=null)=>{try{return JSON.parse(localStorage.getItem(KEY+k))??f}catch{return f}};
function write(k,v){try{localStorage.setItem(KEY+k,JSON.stringify(v));return true}catch{toast('저장 공간을 사용할 수 없어요. 설정에서 파일로 내보내세요.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function persist(){if(state)write('-auto',state)}
function endings(){const a=read('-endings',[]);return Array.isArray(a)?[...new Set(a.filter(x=>x==='solo-normal'||CAST.some(c=>x===c.id+'-good'||x===c.id+'-normal')))]:[]}
let spriteInstance=0;
function sprite(c,look=c.portraitMood??0,extra=''){
 if(look===0||look===1)look+=6;
 if(c.id==='ori'&&look===3)return `<img class="sprite ${extra}" src="assets/generated/ori-home-suit.webp?v=17" alt="오리고기 집에서 입는 베스트 정장">`;
 const family=look>=6?'role':look>=3?'wardrobe':'sprite',frame=look%3,key=family+'-'+c.id+'-'+frame,clip='sprite-clip-'+(++spriteInstance);
 return `<svg class="sprite ${extra}" role="img" aria-label="${c.name} ${LOOK_LABELS[look]}" viewBox="${frame*512} 0 512 1024" xmlns="http://www.w3.org/2000/svg"><defs><clipPath id="${clip}" clipPathUnits="userSpaceOnUse"><polygon points="${SPRITE_CLIPS[key]}"/></clipPath></defs><image href="assets/generated/${family}-${c.id}.webp?v=${c.id==='mone'?18:c.id==='ori'?17:7}" x="0" y="0" width="1536" height="1024" clip-path="url(#${clip})"/></svg>`;
}
function modal(html){$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function close(){if($('#modal').open)$('#modal').close()}
function header(){return `<header class="topbar"><button class="brand" data-action="title">우리 동네, 열한 번의 우연</button>${state?`<div class="clock">${G.day(state)}일차 <b>${G.slot(state)?'저녁':'오후'}</b> <span>${state.money.toLocaleString()}원</span></div>`:''}<nav class="tools" aria-label="게임 메뉴"><button data-action="saves">저장</button><button data-action="journal">수첩</button><button data-action="settings">설정</button></nav></header>`}
function render(){const app=$('#app');document.title='우리 동네, 열한 번의 우연';
 if(screen==='title'){app.innerHTML=`<main class="hero"><div class="eyebrow">AFTERGLOW · CHAPTERS OF US</div><h1>우리 동네,<br>열한 번의 우연</h1><p>우연히 마주친 얼굴이,<br>일부러 만나고 싶은 사람이 되기까지.</p><div class="actions"><button class="primary" data-action="new">새 이야기</button><button data-action="continue" ${read('-auto')?'':'disabled'}>이어하기</button><button data-action="archive">추억 앨범</button></div><small>새로 이어진 이야기 · 11명, 88개의 사건과 22개의 외출</small><footer><p class="ownership-notice">본 게임은 비영리 목적의 팬 창작물입니다.<br>모든 캐릭터 모델의 디자인 소유권은 프로젝트 아이에 있습니다.</p><button data-action="credits">작품 정보</button></footer></main>`;return;}
 app.innerHTML=header();if(state.ending){screen='ending';renderEnding();return}if(state.scene){screen='scene';renderScene();return}screen='map';const over=G.over(state);
 app.insertAdjacentHTML('beforeend',`<main class="layout"><section class="intro"><div><div class="eyebrow">${over?'THE LAST EVENING':'A NEW PROMISE'}</div><h1>${over?'오늘, 마음을 전할 사람은':'누가 기다리고 있을까'}</h1><p>${over?'마지막 저녁, 함께한 시간에 이름을 붙여보세요.':'만남도 휴식도 한 번의 시간. 오늘의 약속은 당신이 골라요.'}</p></div><div class="calendar"><strong>${WORLD.days-G.day(state)+1}</strong><span>남은 날</span></div></section><section class="roster" aria-label="만날 사람">${CAST.map(c=>{const p=state.progress[c.id],a=state.affinity[c.id],ready=G.canConfess(state,c.id),done=p===c.events.length,unavailable=G.availability(state,c);return `<button class="person ${ready?'ready':''}" data-action="meet" data-id="${c.id}" style="--c:${c.color}"><div class="portrait-wrap">${sprite(c)}<span class="availability ${!unavailable?'available':''}">${ready?'♥ 전하고 싶은 마음':done?'마지막 약속':unavailable||'지금 만날 수 있어요'}</span></div><div class="person-copy"><h2>${c.name}</h2><div class="bond-label"><span>${c.place}</span><span>♥ ${a} / 100</span></div><div class="bond" aria-label="친밀도 ${a}/100"><i style="width:${a}%"></i></div><div class="chapter-line"><span>${p}/${c.events.length}화</span><span>${done?'함께한 이야기':esc(c.events[p][0])}</span></div></div></button>`}).join('')}</section><div class="day-actions">${!over?'<button data-action="work">서점 일 돕기 <small>+6,000원 · 시간 1회</small></button><button data-action="rest">집에서 쉬기 <small>다음 시간으로</small></button>':'<button data-action="solo">나만의 마지막 저녁</button>'}<button data-action="archive">추억 앨범</button></div></main>`);}
function renderScene(){rememberLooks(state);const sc=state.scene,c=G.byId(sc.id),l=sc.lines[sc.step];$('#app').insertAdjacentHTML('beforeend',`<main class="stage" data-location="${sc.place}" style="--c:${c.color};--scene-bg:url('assets/generated/bg-${sc.place}.webp')"><button class="art-toggle" data-action="art">그림 보기</button><div class="sceneinfo"><span>${sc.type==='event'?`${sc.index+1}화`:'우리의 약속'}</span> ${esc(sc.title)}</div><div class="scene-figure">${sprite(c,sc.mood)}</div><section class="dialogue" aria-label="대화"><div class="speaker">${l?esc(l[0]==='나'?state.name:l[0]):'당신의 선택'}</div><div class="line" aria-live="polite">${l?esc(l[1]):'어떤 마음을 전할까?'}</div>${l?`<div class="advance"><span>${sc.step+1} / ${sc.lines.length}</span><button class="primary" data-action="next">${sc.step===sc.lines.length-1&&!sc.choice?'만남을 마치기':'다음'} ▷</button></div>`:`<div class="choices">${sc.options.map((o,i)=>`<button data-action="choose" data-index="${i}"><span>${i+1}</span>${esc(o.text)}</button>`).join('')}</div>`}</section></main>`)}
function meet(id){const c=G.byId(id);if(!c)return;const p=state.progress[id],a=state.affinity[id],block=G.availability(state,c),done=p===c.events.length,memory=G.giftMemory(state,id);modal(`<div class="meet-head" style="--c:${c.color}">${sprite(c,done?5:c.portraitMood)}<div><h2>${c.name}</h2><p>♥ ${a} / 100</p><small>${c.hours.length===2?'오후 · 저녁':c.hours[0]===0?'오후':'저녁'}에 만날 수 있어요</small></div></div>${G.canConfess(state,id)?'<p class="ready-text">서로에게 충분히 가까워졌어요. 남은 날짜와 상관없이 마음을 전할 수 있어요.</p><button class="primary wide" data-action="confess" data-id="'+id+'">마음을 전한다 · 결말로</button>':''}<div class="meet-actions">${!done?`<button data-action="visit" data-id="${id}" ${block?'disabled':''}><strong>${p+1}화 · ${esc(c.events[p][0])}</strong><small>${block||'새로운 이야기를 이어가기 · 시간 1회'}</small></button>`:'<p>이 인물의 이야기를 모두 나눴어요. 아직 함께하지 않은 외출이 있다면 약속해보세요.</p>'}<button data-action="outing" data-id="${id}" ${block||p<1||state.dates[id]>=2||state.money<2000?'disabled':''}><strong>${state.dates[id]>=2?'외출 추억을 모두 남겼어요':esc(c.outings[state.dates[id]][0])}</strong><small>함께 외출 · ${state.dates[id]}/2 · 2,000원 · 시간 1회</small></button><button data-action="gifts" data-id="${id}" ${block||p<1||state.gifts[id]?'disabled':''}><strong>${state.gifts[id]?'마음을 담은 선물을 건넸어요':'대화에서 기억한 선물'}</strong><small>${memory?'기억해둔 취향을 선물로 · 시간 1회':'대화를 나누며 선물의 단서를 찾아보세요'}</small></button>${a<G.ROMANCE_THRESHOLD&&(done||G.over(state)&&p>=3)?`<button data-action="friend" data-id="${id}">좋은 사이로 남는다 · 우정 결말</button>`:''}</div>${memory?`<details><summary>수첩에 적어둔 기억</summary>${giftClue(c,memory)}</details>`:''}`)}
function finish(id){if(!G.finish(state,id))return;write('-endings',[...new Set([...endings(),id+'-'+state.ending.kind])]);close();persist();render();window.scrollTo(0,0)}
function renderEnding(){rememberLooks(state);const e=state.ending,c=G.byId(e.id),[title,text]=G.endingInfo(state),pages=G.endingPages(state),idx=e.page||0,page=pages?.[idx],last=!pages||idx===pages.length-1;
$('#app').insertAdjacentHTML('beforeend',`<main class="ending" style="--scene-bg:url('assets/generated/bg-${page?.[0]||c?.home||'park'}.webp')">${c?`<div class="ending-figure">${sprite(c,page?.[3]??c?.normalMood??2)}</div>`:''}<article><div class="eyebrow">${pages?['CONFESSION','OUR FIRST DATE','AFTER THE BEGINNING'][idx]:e.id==='solo'?'MY OWN STORY':'A FRIEND TO COME HOME TO'}</div><div class="ending-series">${esc(title)}${pages?` · ${idx+1} / ${pages.length}`:''}</div><h1>${esc(page?.[1]||title)}</h1><div class="ending-prose">${(page?.[2]||text).split('\n').map(t=>`<p>${esc(t)}</p>`).join('')}</div><div class="actions">${e.id==='siho'&&e.kind==='good'&&idx===0?'<button data-action="pet-name" data-id="여보">여보라고 불러줘 · 첫 데이트로 ▷</button><button data-action="pet-name" data-id="오빠">오빠라고 불러줘 · 첫 데이트로 ▷</button>':''}${idx>0?'<button data-action="ending-prev">이전 장면</button>':''}${!last?'<button class="primary" data-action="ending-next" '+(e.id==='siho'&&!e.petName?'disabled':'')+'>'+(idx===0?'첫 데이트로':'그 뒤의 우리')+' ▷</button>':'<button class="primary" data-action="new">다른 이야기</button><button data-action="archive">추억 앨범</button><button data-action="after">결말 전 동네로</button>'}</div></article></main>`)}
function newGame(){modal('<h2>새로운 골목으로</h2><p>스물여덟 날, 오후와 저녁에 한 번씩.<br>상대의 시간을 살피고, 대화에서 알게 된 취향을 기억해보세요. 충분히 가까워졌다면 마지막 날을 기다리지 않아도 괜찮아요.</p><form id="newForm" class="form"><label>당신을 부를 이름<input name="player" type="text" maxlength="16" placeholder="이웃" autocomplete="off"></label><small id="name-bonus" aria-live="polite">팬덤명이 포함된 이름에는 작은 인연이 기다려요.</small><small>자동 저장은 새 이야기로 바뀝니다. 수동 저장과 추억 앨범은 유지돼요.</small><button class="primary" type="submit">이사 첫날 시작하기</button></form>');const nameInput=$('#newForm input');nameInput.oninput=()=>{const ids=G.nameBonuses(nameInput.value);$('#name-bonus').textContent=ids.length?ids.map(id=>G.byId(id).name+' 친밀도 +'+G.FANDOM_BONUS).join(' · '):'팬덤명이 포함된 이름에는 작은 인연이 기다려요.';};$('#newForm').onsubmit=e=>{e.preventDefault();state=G.fresh(new FormData(e.target).get('player'));journalPerson='all';screen='map';persist();close();render();window.scrollTo(0,0)}}
function load(k){const original=read('-'+k),s=G.migrate(original);if(!s){toast('저장 파일을 읽을 수 없어요.');return}state=s;screen='map';close();persist();render();if(original.version===1)toast('기존 기록을 옮겼어요. 이어지는 4화부터 새 이야기를 만날 수 있어요.');window.scrollTo(0,0)}
function saves(){modal(`<h2>저장 / 불러오기</h2><p>기기마다 저장돼요. 다른 기기로 옮기려면 설정에서 저장 파일을 내보내세요.</p>${['auto','1','2','3'].map(k=>{const s=read('-'+k);return `<div class="save-slot"><div><b>${k==='auto'?'자동 저장':'저장 '+k}</b><p>${s?esc(s.name)+' · '+Math.min(28,Math.floor(s.turn/2)+1)+'일차'+(s.version===1?' · 이전 버전':''):'비어 있음'}</p></div>${k!=='auto'?`<button data-action="save" data-id="${k}" ${!state?'disabled':''}>저장</button>`:''}<button data-action="load" data-id="${k}" ${s?'':'disabled'}>불러오기</button></div>`}).join('')}`)}
function galleryCollection(){return Gallery.clean(read('-gallery',[]));}
function rememberLooks(s){const previous=galleryCollection(),next=Gallery.merge(previous,Gallery.seen(s));if(next.length!==previous.length)write('-gallery',next);return next;}
let albumPerson='';
function archive(id=albumPerson){if(!G.byId(id))id=CAST[0].id;albumPerson=id;
 for(const k of ['auto','1','2','3']){const saved=G.migrate(read('-'+k));if(saved)rememberLooks(saved);}if(state)rememberLooks(state);
 const a=endings(),restored=Gallery.merge(galleryCollection(),Gallery.fromEndings(a));if(restored.length!==galleryCollection().length)write('-gallery',restored);
 const found=restored,c=G.byId(id),groups=Gallery.outfits(c).sort((a,b)=>Number(b.looks.some(n=>found.includes(id+':'+n)))-Number(a.looks.some(n=>found.includes(id+':'+n)))),count=groups.filter(g=>g.looks.some(n=>found.includes(id+':'+n))).length;
 modal(`<h2>추억 앨범</h2><label class="journal-filter">함께한 사람<select id="album-person">${CAST.map(c=>`<option value="${c.id}" ${id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><p>${esc(c.name)}의 옷장 · 총 ${groups.length}벌 중 ${count}벌 해금</p><div class="wardrobe-grid">${groups.map((g,i)=>{const look=g.looks.find(n=>found.includes(id+':'+n));return look!==undefined?`<button class="wardrobe-card" data-action="gallery-look" data-id="${id}" data-look="${look}">${sprite(c,look)}<strong>${esc(g.name)}</strong><small>크게 보기</small></button>`:`<div class="wardrobe-card locked"><div class="locked-art" aria-hidden="true">?</div><strong>아직 만나지 못한 모습</strong><small>이야기와 외출에서 발견해보세요</small></div>`;}).join('')}</div><p class="journal-note">본 의상은 새 이야기를 시작해도 남아요. 표정은 같은 의상 안에서 모아 볼 수 있어요.</p><h3>우리의 결말</h3><div class="modal-actions">${['good','normal'].map(k=>`<button data-action="replay" data-id="${id}" data-kind="${k}" ${a.includes(id+'-'+k)?'':'disabled'}>${a.includes(id+'-'+k)?esc(c[k][0]):k==='good'?'아직 전하지 않은 마음':'아직 남기지 않은 우정'}</button>`).join('')}</div><details><summary>나만의 이야기</summary><button data-action="replay" data-id="solo" data-kind="normal" ${a.includes('solo-normal')?'':'disabled'}>익숙해진 골목</button></details>`);
 $('#album-person').onchange=e=>{archive(e.target.value);$('#modal').scrollTop=0;$('#album-person').focus();};
}
function galleryLook(id,look){const c=G.byId(id),found=galleryCollection();if(!c||!(found.includes(id+':'+look)||(look===6&&found.includes(id+':0'))||(look===7&&found.includes(id+':1'))))return;const source=Gallery.outfits(c).find(g=>g.looks.includes(look));if(!source)return;const group={...source,looks:[...new Set(source.looks.map(n=>n<2?n+6:n))]};const unlocked=n=>found.includes(id+':'+n)||(n===6&&found.includes(id+':0'))||(n===7&&found.includes(id+':1'));if(look<2)look+=6;
 const expression=n=>n===1||n===7?'진지한 표정':n===8?'미소':'기본 표정';
 modal(`<button data-action="archive" data-id="${id}">‹ ${esc(c.name)}의 옷장</button><h2>${esc(group.name)}</h2><div class="gallery-full">${sprite(c,look)}</div>${group.looks.length>1?`<div class="modal-actions">${group.looks.map(n=>`<button data-action="gallery-look" data-id="${id}" data-look="${n}" aria-pressed="${n===look}" ${unlocked(n)?'':'disabled'}>${unlocked(n)?expression(n):'미발견 표정'}</button>`).join('')}</div>`:''}`);
 $('#modal').scrollTop=0;
}

function giftClue(c,memory){return `<div class="gift-clue"><strong>${esc(c.name)} · ${esc(memory.name)}</strong><p>${esc(memory.clue)}</p>${memory.quote?`<blockquote>“${esc(memory.quote)}”</blockquote>`:''}</div>`}
function observationEntry(o){const delta=Number(o.delta)||0;return `<details class="journal-observation"><summary><span>${o.day}일차 · ${esc(G.byId(o.characterId)?.name||'함께한 기억')}</span><strong>${esc(o.title)}</strong><small class="bond-change ${delta<0?'negative':delta>0?'positive':''}">친밀도 ${delta>0?'+':''}${delta}</small></summary><div class="observation-body"><p><b>내가 전한 말과 마음</b>${esc(o.choice)}</p><p><b>돌아온 답</b>${esc(o.reply)}</p><p class="observation-note">${esc(o.note)}</p></div></details>`}
let journalPerson='all';
function journal(id=journalPerson){journalPerson=id==='all'||G.byId(id)?id:'all';id=journalPerson;
 if(!state){modal('<h2>작은 수첩</h2><p>함께 나눈 시간이 여기에 남아요.</p>');return;}
 const groups=G.conversations(state,id),people=CAST.filter(c=>state.progress[c.id]>0||state.scene?.id===c.id||state.log.some(l=>l.characterId===c.id||l.speaker===c.name)),selected=G.byId(id),memories=(selected?[selected]:people).map(c=>({c,memory:G.giftMemory(state,c.id)})).filter(x=>x.memory),observations=G.observations(state,id);
 modal(`<h2>작은 수첩</h2><label class="journal-filter">누구와 나눈 이야기를 볼까요?<select id="journal-person"><option value="all">모든 인물</option>${people.map(c=>`<option value="${c.id}" ${id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>
 <h3>기억해둔 취향</h3>${memories.length?`<details class="journal-memories" ${selected?'open':''}><summary>${selected?esc(selected.name)+'의 이야기에서':'대화에서 발견한 단서 · '+memories.length+'명'}</summary>${memories.map(({c,memory})=>giftClue(c,memory)).join('')}</details>`:'<p class="journal-note">함께 이야기를 나누다 알게 된 취향을 여기에 적어둘게요.</p>'}
 <details class="journal-observations"><summary>선택 뒤에 남은 마음 · ${observations.length}개</summary><p class="journal-note">상대의 답을 듣고 내가 느낀 점이에요.</p>${observations.length?[...observations].reverse().map(observationEntry).join(''):'<p>선택을 나누면 그때의 반응도 함께 남길게요.</p>'}</details>
 <h3>대화 다시 보기</h3>${groups.length?groups.map((g,i)=>`<details class="journal-scene" ${i===groups.length-1?'open':''}><summary><span>${g.day}일차 · ${esc(G.byId(g.characterId)?.name||'공통 기록')}</span><strong>${esc(g.title)}</strong><small>${g.lines.length}개의 대화</small></summary>${g.lines.map(l=>`<div class="log-entry ${!l.speaker?'narration':''}"><b>${esc(l.speaker||'이야기')}</b><p>${esc(l.text)}</p></div>`).join('')}</details>`).join(''):'<p>아직 나눈 대화가 없어요. 첫 만남부터 여기에 남길게요.</p>'}
 ${state.log.some(l=>!l.characterId)?'<p class="journal-note">이전 저장의 인물이 확인되지 않는 설명과 내 대사는 ‘모든 인물’의 공통 기록에서 볼 수 있어요.</p>':''}
 <details><summary>함께한 날들</summary>${state.journal.filter(j=>id==='all'||j.id===id).map(j=>`<div class="log-entry"><b>${j.day}일차 · ${esc(G.byId(j.id)?.name||state.name)}</b><p>${esc(j.title)}</p></div>`).join('')||'<p>아직 기록이 없어요.</p>'}</details>`);
 $('#journal-person').onchange=e=>{journal(e.target.value);$('#modal').scrollTop=0;$('#journal-person').focus();};
}

function gifts(id){const c=G.byId(id),memory=G.giftMemory(state,id);if(!c)return;modal(`<h2>대화에서 기억한 선물</h2>${memory?`<p>${esc(c.name)}가 이야기했던 취향이 떠올랐다.</p>${giftClue(c,memory)}<div class="meet-actions"><button data-action="gift" data-id="${id}" data-gift="${esc(memory.id)}" ${state.money<memory.cost||state.gifts[id]||G.availability(state,c)?'disabled':''}><strong>${esc(memory.name)} 건네기</strong><small>${memory.cost.toLocaleString()}원 · 시간 1회${state.gifts[id]?' · 이미 마음을 전했어요':state.money<memory.cost?' · 가진 돈이 부족해요':''}</small></button></div>`:'<p>아직 어떤 선물이 떠오를지 모르겠다. 조금 더 이야기를 나누며 기억해두자.</p>'}<button data-action="journal">수첩 펼치기</button>`)}
function settings(){modal(`<h2>설정</h2><div class="form"><p>Space / Enter: 다음 대화<br>1 / 2 / 3: 선택지<br>Escape: 열린 창 닫기</p><button data-action="export" ${state?'':'disabled'}>현재 저장 파일 내보내기</button><label>저장 가져오기<input id="import" type="file" accept="application/json,.json"></label><small>이전 버전 저장도 가져올 수 있어요.</small></div>`);$('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error();const d=JSON.parse(await f.text()),s=G.migrate(d.state);if(!s||!Array.isArray(d.endings)||d.endings.some(x=>x!=='solo-normal'&&!CAST.some(c=>x===c.id+'-good'||x===c.id+'-normal')))throw Error();if(d.gallery!==undefined&&(!Array.isArray(d.gallery)||d.gallery.length>99||Gallery.clean(d.gallery).length!==d.gallery.length))throw Error();state=s;write('-gallery',Gallery.merge(galleryCollection(),d.gallery||[],Gallery.seen(s)));write('-endings',[...new Set([...endings(),...d.endings])]);persist();screen='map';close();render();toast('저장 파일을 가져왔어요.')}catch{toast('올바른 저장 파일이 아니에요.')}}}
function credits(){modal('<h2>작품 정보</h2><p>우리 동네, 열한 번의 우연<br>비공식 팬 창작 · 웹 비주얼 노벨</p><h3>이야기와 그림</h3><p>직업·관계·사건·대사는 별도의 성인 일상 로맨스 세계관을 위한 창작입니다. 실제 인물의 사생활을 묘사하지 않습니다.</p><p>캐릭터 그림은 제공된 기본 디자인을 참고하여 이 게임용으로 새로 생성했습니다. 오리고기는 사용자가 지정한 노란 머리·하얀 오리를 반영한 게임용 창작 디자인입니다. 본 게임은 비영리 목적의 팬 창작물입니다. 모든 캐릭터 모델의 디자인 소유권은 프로젝트 아이에 있습니다.</p><p>장소 배경과 캐릭터 표정·의상은 게임용 생성 이미지입니다. 저장은 브라우저에 보관되며 내보내기로 기기 사이에 옮길 수 있습니다.</p>')}
function action(a,id,b){switch(a){case'art':{const stage=$('.stage');const shown=stage.classList.toggle('art-only');b.textContent=shown?'대화 보기':'그림 보기';return;}case'new':newGame();return;case'continue':load('auto');return;case'load':load(id);return;case'title':screen='title';persist();render();return;case'meet':meet(id);return;case'gifts':gifts(id);return;case'visit':case'outing':case'gift':{const ok=a==='visit'?G.visit(state,id):a==='outing'?G.outing(state,id):G.gift(state,id,b.dataset.gift);if(!ok){toast('지금은 이 약속을 잡을 수 없어요.');return}close();break;}case'next':{const previous=state.scene;G.next(state);if(!state.scene&&previous){toast(G.canConfess(state,previous.id)?'마음을 전할 준비가 되었어요. 동네에서 결말을 선택할 수 있어요.':`${G.byId(previous.id).name}와의 시간을 수첩에 남겼어요.`);}break;}case'choose':G.choose(state,Number(b.dataset.index));break;case'rest':G.pass(state);break;case'work':G.pass(state,true);toast('서점 일을 돕고 6,000원을 받았어요.');break;case'confess':modal(`<h2>마음을 전할까요?</h2><p>${G.byId(id).name}와 충분히 가까워졌어요. 지금 고백하면 이 인물과의 로맨스 결말로 이어집니다.</p><div class="actions"><button class="primary" data-action="finish" data-id="${id}">마음을 전한다</button><button data-action="close">조금 더 함께한다</button></div>`);return;case'friend':modal(`<h2>함께한 시간에 이름 붙이기</h2><p>서로를 응원하는 사이로 이 이야기를 마칠까요?</p><button data-action="finish" data-id="${id}">우정 결말 보기</button>`);return;case'finish':finish(id);return;case'solo':finish('solo');return;case'pet-name':if(!G.choosePetName(state,id))return;write('-siho-pet-name',id);break;case'ending-next':if(state.ending?.id==='siho'&&state.ending.kind==='good'&&!state.ending.petName)return;if(state.ending)state.ending.page=Math.min(2,(state.ending.page||0)+1);break;case'ending-prev':if(state.ending)state.ending.page=Math.max(0,(state.ending.page||0)-1);break;case'after':state.ending=null;screen='map';break;case'saves':saves();return;case'save':if(state&&write('-'+id,state)){toast('저장했어요.');saves()}return;case'archive':archive(id||albumPerson);return;case'gallery-look':galleryLook(id,Number(b.dataset.look));return;case'journal':journal();return;case'settings':settings();return;case'credits':credits();return;case'close':close();return;case'replay':{const [title,text]=G.endingInfo({ending:{id,kind:b.dataset.kind,...(id==='siho'&&b.dataset.kind==='good'&&['여보','오빠'].includes(read('-siho-pet-name'))?{petName:read('-siho-pet-name')}:{})}});modal(`<h2>${esc(title)}</h2><p style="white-space:pre-line">${esc(text)}</p><button data-action="archive">앨범으로</button>`);return;}case'export':{const blob=new Blob([JSON.stringify({state,endings:endings(),gallery:galleryCollection()})],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='afterglow-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);return;}default:return;}persist();render();if(!state.scene)window.scrollTo(0,0)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)action(b.dataset.action,b.dataset.id,b)});$('#closeModal').onclick=close;
document.addEventListener('keydown',e=>{if($('#modal').open||screen!=='scene'||/INPUT|TEXTAREA/.test(document.activeElement?.tagName))return;if(['1','2','3'].includes(e.key)){e.preventDefault();action('choose',null,{dataset:{index:Number(e.key)-1}})}else if((e.key===' '||e.key==='Enter')&&document.activeElement?.tagName!=='BUTTON'&&state.scene.step<state.scene.lines.length){e.preventDefault();action('next')}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)persist()});render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const snapshot=()=>({screen,day:state?G.day(state):null,turn:state?.turn??null,scene:state?.scene?{character:state.scene.id,title:state.scene.title,location:state.scene.place,line:state.scene.lines[state.scene.step]??null,choices:state.scene.choice&&state.scene.step===state.scene.lines.length?state.scene.options.map(o=>o.text):[]}:null,ending:state?.ending??null});for(const [name,readonly,description] of [['read_story_state',true,'Read the current visible story and choices without changing progress.'],['advance_story_dialogue',false,'Advance one visible dialogue line. Never chooses responses or advances past a modal.']])try{Promise.resolve(document.modelContext.registerTool({name,description,inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:readonly,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected empty input');if(!readonly){if(screen!=='scene'||!state?.scene||$('#modal').open||state.scene.step>=state.scene.lines.length)throw Error('No dialogue to advance');action('next')}return snapshot()}},{signal:lifecycle.signal})).catch(()=>{})}catch{}window.addEventListener('pagehide',e=>{if(!e.persisted)lifecycle.abort()},{once:true})}
